# Local optimisers
# ---------------------------------------------------------------------


@dataclass
class GradientDescent(Optimiser):
    learning_rate: float = 1e-3
    tolerance: float = 1e-8

    def run(
        self,
        problem: Problem,
        x0=None,
        max_evals=500,
        seed=0,
    ) -&gt; RunResult:
        x = self._start(
            problem,
            x0,
            max_evals,
        )

        trajectory = [x.copy()]

        success = False
        message = "evaluation budget reached"

        try:
            while True:
                problem(x)
                gradient = problem.grad(x)

                if (
                    np.linalg.norm(gradient)
                    &lt;= self.tolerance
                ):
                    success = True
                    message = (
                        "gradient tolerance reached"
                    )
                    break

                x = (
                    x
                    - self.learning_rate
                    * gradient
                )

                trajectory.append(x.copy())

        except EvaluationBudgetExceeded:
            pass

        return self._result(
            problem,
            trajectory,
            success,
            message,
        )


@dataclass
class Momentum(Optimiser):
    learning_rate: float = 1e-3
    momentum: float = 0.9
    tolerance: float = 1e-8

    def run(
        self,
        problem: Problem,
        x0=None,
        max_evals=500,
        seed=0,
    ) -&gt; RunResult:
        x = self._start(
            problem,
            x0,
            max_evals,
        )

        velocity = np.zeros_like(x)
        trajectory = [x.copy()]

        success = False
        message = "evaluation budget reached"

        try:
            while True:
                problem(x)
                gradient = problem.grad(x)

                if (
                    np.linalg.norm(gradient)
                    &lt;= self.tolerance
                ):
                    success = True
                    message = (
                        "gradient tolerance reached"
                    )
                    break

                velocity = (
                    self.momentum * velocity
                    - self.learning_rate
                    * gradient
                )

                x = x + velocity
                trajectory.append(x.copy())

        except EvaluationBudgetExceeded:
            pass

        return self._result(
            problem,
            trajectory,
            success,
            message,
        )


@dataclass
class Adam(Optimiser):
    learning_rate: float = 0.03
    beta1: float = 0.9
    beta2: float = 0.999
    epsilon: float = 1e-8
    tolerance: float = 1e-8

    def run(
        self,
        problem: Problem,
        x0=None,
        max_evals=500,
        seed=0,
    ) -&gt; RunResult:
        x = self._start(
            problem,
            x0,
            max_evals,
        )

        first_moment = np.zeros_like(x)
        second_moment = np.zeros_like(x)

        trajectory = [x.copy()]

        success = False
        message = "evaluation budget reached"
        iteration = 0

        try:
            while True:
                problem(x)
                gradient = problem.grad(x)

                if (
                    np.linalg.norm(gradient)
                    &lt;= self.tolerance
                ):
                    success = True
                    message = (
                        "gradient tolerance reached"
                    )
                    break

                iteration += 1

                first_moment = (
                    self.beta1 * first_moment
                    + (1 - self.beta1)
                    * gradient
                )

                second_moment = (
                    self.beta2 * second_moment
                    + (1 - self.beta2)
                    * gradient**2
                )

                corrected_first = (
                    first_moment
                    / (1 - self.beta1**iteration)
                )

                corrected_second = (
                    second_moment
                    / (1 - self.beta2**iteration)
                )

                x = (
                    x
                    - self.learning_rate
                    * corrected_first
                    / (
                        np.sqrt(corrected_second)
                        + self.epsilon
                    )
                )

                trajectory.append(x.copy())

        except EvaluationBudgetExceeded:
            pass

        return self._result(
            problem,
            trajectory,
            success,
            message,
        )


@dataclass
class Newton(Optimiser):
    tolerance: float = 1e-8
    damping: float = 1.0

    def run(
        self,
        problem: Problem,
        x0=None,
        max_evals=500,
        seed=0,
    ) -&gt; RunResult:
        x = self._start(
            problem,
            x0,
            max_evals,
        )

        trajectory = [x.copy()]

        success = False
        message = "evaluation budget reached"

        try:
            while True:
                problem(x)
                gradient = problem.grad(x)

                if (
                    np.linalg.norm(gradient)
                    &lt;= self.tolerance
                ):
                    success = True
                    message = (
                        "gradient tolerance reached"
                    )
                    break

                step = np.linalg.solve(
                    problem.hessian(x),
                    gradient,
                )

                x = (
                    x
                    - self.damping * step
                )

                trajectory.append(x.copy())

        except EvaluationBudgetExceeded:
            pass

        except np.linalg.LinAlgError:
            message = "singular Hessian"

        return self._result(
            problem,
            trajectory,
            success,
            message,
        )


@dataclass
class ScipyMinimise(Optimiser):
    """Adapter for SciPy local optimisation methods."""

    method: str = "Nelder-Mead"
    use_gradient: bool = False
    options: dict = field(default_factory=dict)

    def run(
        self,
        problem: Problem,
        x0=None,
        max_evals=500,
        seed=0,
    ) -&gt; RunResult:
        from scipy.optimize import minimize

        x = self._start(
            problem,
            x0,
            max_evals,
        )

        trajectory = [x.copy()]

        def callback(xk: Vector) -&gt; None:
            trajectory.append(
                np.asarray(
                    xk,
                    dtype=float,
                ).copy()
            )

        try:
            if self.method.lower() in {
                "nelder-mead",
                "powell",
            }:
                budget_option = {
                    "maxfev": max_evals
                }
            else:
                budget_option = {
                    "maxiter": max_evals
                }

            result = minimize(
                problem,
                x,
                jac=(
                    problem.grad
                    if self.use_gradient
                    else None
                ),
                method=self.method,
                callback=callback,
                options={
                    **budget_option,
                    **self.options,
                },
            )

            success = bool(result.success)
            message = str(result.message)

        except EvaluationBudgetExceeded:
            success = False
            message = "evaluation budget reached"

        return self._result(
            problem,
            trajectory,
            success,
            message,
        )


def default_problems() -&gt; dict[str, Problem]:
    problems = {
        "quadratic": Quadratic(),
        "rosenbrock": Rosenbrock(),
        "himmelblau": Himmelblau(),
        "rastrigin": Rastrigin(),
    }

    print(
        "Loaded default optimisation problems: "
        + ", ".join(problem.name for problem in problems.values())
    )

    return problems


def local_optimisers() -&gt; dict[str, Optimiser]:
    """Local optimisers used in the default comparison matrix."""
    opts = {
        "nelder_mead": ScipyMinimise(
            "Nelder-Mead"
        ),
        "gradient_descent": GradientDescent(),
        "momentum": Momentum(),
        "adam": Adam(),
        "bfgs": ScipyMinimise(
            "BFGS",
            use_gradient=True,
        ),
        "newton": Newton(),
    }

    print(
        "Loaded local optimisers: "
        + ", ".join(
                    o
                    .replace("_", " ")
                    .title()
 for o in opts.keys())
    )
    return opts


def global_optimisers() -&gt; dict[str, Optimiser]:
    """Global optimisers, separate from the default local methods."""
    opts = {
        "random_search": RandomSearch(),
        "simulated_annealing": (
            SimulatedAnnealing()
        ),
        "bayesian_optimisation": (
            BayesianOptimisation()
        ),
    }
    print(
        "Loaded global optimisers: "
        + ", ".join(
                    o
                    .replace("_", " ")
                    .title()
 for o in opts.keys())
    )
    return opts
</pre> #@title from __future__ import annotations  from abc import ABC, abstractmethod from dataclasses import dataclass, field from typing import Sequence  import numpy as np from numpy.typing import ArrayLike, NDArray   Vector = NDArray[np.float64]   class EvaluationBudgetExceeded(RuntimeError):     """Raised before an objective evaluation would exceed the budget."""   @dataclass(frozen=True) class Evaluation:     n_eval: int     x: Vector     value: float     best_x: Vector     best_value: float   @dataclass class RunResult:     optimiser: str     problem: str     x_best: Vector     f_best: float     n_objective_evals: int     n_gradient_evals: int     n_hessian_evals: int     evaluations: list[Evaluation]     trajectory: list[Vector]     success: bool     message: str = ""      @property     def eval_numbers(self) -&gt; NDArray[np.int_]:         return np.asarray([item.n_eval for item in self.evaluations])      @property     def best_values(self) -&gt; Vector:         """Best objective found so far after each objective evaluation."""         return np.asarray([item.best_value for item in self.evaluations])   class Problem(ABC):     """Base class providing a simple API and automatic evaluation tracking.      ``true_minima`` stores every known global minimiser, allowing plotting code     to distinguish the known solution from the best point found by an optimiser.     """      def __init__(         self,         name: str,         bounds: Sequence[tuple[float, float]],         x0: ArrayLike,         true_minima: Sequence[ArrayLike] = (),     ) -&gt; None:         self.name = name         self.bounds = tuple((float(lo), float(hi)) for lo, hi in bounds)         self.x0 = np.asarray(x0, dtype=float)         self.true_minima = tuple(             np.asarray(x, dtype=float) for x in true_minima         )          if self.x0.shape != (len(self.bounds),):             raise ValueError("x0 must have one entry per bound")          if any(x.shape != self.x0.shape for x in self.true_minima):             raise ValueError(                 "each true minimum must have one entry per bound"             )          self.reset()      @property     def dimension(self) -&gt; int:         return len(self.bounds)      def reset(self, max_objective_evals: int | None = None) -&gt; None:         self.max_objective_evals = max_objective_evals         self.n_objective_evals = 0         self.n_gradient_evals = 0         self.n_hessian_evals = 0         self.evaluations: list[Evaluation] = []         self.best_x: Vector | None = None         self.best_value = np.inf      def __call__(self, x: ArrayLike) -&gt; float:         """Evaluate and record the objective: ``problem(x)``."""         if (             self.max_objective_evals is not None             and self.n_objective_evals &gt;= self.max_objective_evals         ):             raise EvaluationBudgetExceeded          x = self._validate_x(x)         value = float(self.objective(x))          self.n_objective_evals += 1          if value &lt; self.best_value:             self.best_value = value             self.best_x = x.copy()          assert self.best_x is not None          self.evaluations.append(             Evaluation(                 n_eval=self.n_objective_evals,                 x=x.copy(),                 value=value,                 best_x=self.best_x.copy(),                 best_value=self.best_value,             )         )          return value      def grad(self, x: ArrayLike) -&gt; Vector:         self.n_gradient_evals += 1         return np.asarray(             self.gradient(self._validate_x(x)),             dtype=float,         )      def hessian(self, x: ArrayLike) -&gt; NDArray[np.float64]:         self.n_hessian_evals += 1         return np.asarray(             self.hess(self._validate_x(x)),             dtype=float,         )      def evaluate(self, x: ArrayLike) -&gt; float:         """Untracked evaluation, useful when drawing the objective landscape."""         return float(self.objective(self._validate_x(x)))      def _validate_x(self, x: ArrayLike) -&gt; Vector:         x = np.asarray(x, dtype=float)          if x.shape != (self.dimension,):             raise ValueError(                 f"expected shape ({self.dimension},), got {x.shape}"             )          return x      @abstractmethod     def objective(self, x: Vector) -&gt; float:         ...      def gradient(self, x: Vector) -&gt; Vector:         raise NotImplementedError(             f"{self.name} does not provide a gradient"         )      def hess(self, x: Vector) -&gt; NDArray[np.float64]:         raise NotImplementedError(             f"{self.name} does not provide a Hessian"         )      def plot_contours(         self,         *,         ax=None,         resolution: int = 200,         levels: int = 30,         scale: str = "log",         cmap: str = "inferno",         contour_lines: bool = True,         colorbar: bool = True,         show_true_minima: bool = True,     ):         """Plot this objective when the problem is two-dimensional.          Grid evaluations are untracked, so plotting does not consume         the optimiser's objective-evaluation budget.          Returns         -------         fig, ax, contour         """         import matplotlib.pyplot as plt          if self.dimension != 2:             raise ValueError(                 "Contour plots require a two-dimensional problem"             )          if resolution &lt; 2 or levels &lt; 2:             raise ValueError(                 "resolution and levels must both be at least 2"             )          if ax is None:             fig, ax = plt.subplots(figsize=(6, 5))         else:             fig = ax.figure          (x1_min, x1_max), (x2_min, x2_max) = self.bounds          x1 = np.linspace(x1_min, x1_max, resolution)         x2 = np.linspace(x2_min, x2_max, resolution)         X1, X2 = np.meshgrid(x1, x2)          Z = np.empty_like(X1)          for index in np.ndindex(X1.shape):             Z[index] = self.evaluate(                 [X1[index], X2[index]]             )          shifted = Z - np.nanmin(Z)          if scale == "linear":             display_Z = Z          elif scale == "log":             positive = shifted[shifted &gt; 0]              reference = (                 np.nanpercentile(positive, 5)                 if positive.size                 else 1.0             )              reference = max(                 reference,                 np.finfo(float).eps,             )              display_Z = np.log1p(                 shifted / reference             )          elif scale == "sqrt":             display_Z = np.sqrt(shifted)          else:             raise ValueError(                 "scale must be 'linear', 'log', or 'sqrt'"             )          contour_levels = np.linspace(             np.nanmin(display_Z),             np.nanmax(display_Z),             levels,         )          contour = ax.contourf(             X1,             X2,             display_Z,             levels=contour_levels,             cmap=cmap,         )          if contour_lines:             ax.contour(                 X1,                 X2,                 display_Z,                 levels=contour_levels[::3],                 colors="black",                 linewidths=0.4,                 alpha=0.5,             )          if show_true_minima and self.true_minima:             minima = np.asarray(self.true_minima)              ax.scatter(                 minima[:, 0],                 minima[:, 1],                 marker="X",                 s=70,                 facecolor="cyan",                 edgecolor="black",                 label="True minimum",                 zorder=5,             )          if colorbar:             fig.colorbar(                 contour,                 ax=ax,                 label=f"Objective ({scale} display scale)",             )          ax.set(             xlim=self.bounds[0],             ylim=self.bounds[1],             xlabel=r"$x_1$",             ylabel=r"$x_2$",             title=self.name,         )          return fig, ax, contour   class Quadratic(Problem):     def __init__(self, condition: float = 100.0) -&gt; None:         self.A = np.diag([1.0, float(condition)])          super().__init__(             name="Quadratic",             bounds=[(-3, 3), (-3, 3)],             x0=[2, 2],             true_minima=[[0, 0]],         )      def objective(self, x: Vector) -&gt; float:         return float(0.5 * x @ self.A @ x)      def gradient(self, x: Vector) -&gt; Vector:         return self.A @ x      def hess(self, x: Vector) -&gt; NDArray[np.float64]:         return self.A.copy()   class Rosenbrock(Problem):     def __init__(self) -&gt; None:         super().__init__(             name="Rosenbrock",             bounds=[(-2, 2), (-1, 3)],             x0=[-1.5, 2.0],             true_minima=[[1, 1]],         )      def objective(self, x: Vector) -&gt; float:         return float(             (1 - x[0]) ** 2             + 100 * (x[1] - x[0] ** 2) ** 2         )      def gradient(self, x: Vector) -&gt; Vector:         return np.array(             [                 2 * (x[0] - 1)                 - 400 * x[0] * (x[1] - x[0] ** 2),                 200 * (x[1] - x[0] ** 2),             ]         )      def hess(self, x: Vector) -&gt; NDArray[np.float64]:         return np.array(             [                 [                     1200 * x[0] ** 2 - 400 * x[1] + 2,                     -400 * x[0],                 ],                 [                     -400 * x[0],                     200,                 ],             ]         )   class Himmelblau(Problem):     def __init__(self) -&gt; None:         super().__init__(             name="Himmelblau",             bounds=[(-5, 5), (-5, 5)],             x0=[0, 0],             true_minima=[                 [3.0, 2.0],                 [-2.805118, 3.131312],                 [-3.779310, -3.283186],                 [3.584428, -1.848126],             ],         )      def objective(self, x: Vector) -&gt; float:         a = x[0] ** 2 + x[1] - 11         b = x[0] + x[1] ** 2 - 7          return float(a * a + b * b)      def gradient(self, x: Vector) -&gt; Vector:         a = x[0] ** 2 + x[1] - 11         b = x[0] + x[1] ** 2 - 7          return np.array(             [                 4 * x[0] * a + 2 * b,                 2 * a + 4 * x[1] * b,             ]         )      def hess(self, x: Vector) -&gt; NDArray[np.float64]:         return np.array(             [                 [                     12 * x[0] ** 2 + 4 * x[1] - 42,                     4 * (x[0] + x[1]),                 ],                 [                     4 * (x[0] + x[1]),                     4 * x[0] + 12 * x[1] ** 2 - 26,                 ],             ]         )   class Rastrigin(Problem):     def __init__(self, dimension: int = 2) -&gt; None:         bounds = [(-5.12, 5.12)] * dimension          super().__init__(             name="Rastrigin",             bounds=bounds,             x0=[3.5] * dimension,             true_minima=[[0.0] * dimension],         )      def objective(self, x: Vector) -&gt; float:         return float(             10 * self.dimension             + np.sum(                 x * x - 10 * np.cos(2 * np.pi * x)             )         )      def gradient(self, x: Vector) -&gt; Vector:         return (             2 * x             + 20 * np.pi * np.sin(2 * np.pi * x)         )      def hess(self, x: Vector) -&gt; NDArray[np.float64]:         diagonal = (             2             + 40 * np.pi**2 * np.cos(2 * np.pi * x)         )          return np.diag(diagonal)   class Optimiser(ABC):     @abstractmethod     def run(         self,         problem: Problem,         x0: ArrayLike | None = None,         max_evals: int = 500,         seed: int = 0,     ) -&gt; RunResult:         ...      def _start(         self,         problem: Problem,         x0: ArrayLike | None,         max_evals: int,     ) -&gt; Vector:         problem.reset(max_evals)          return problem._validate_x(             problem.x0 if x0 is None else x0         ).copy()      def _result(         self,         problem: Problem,         trajectory: list[Vector],         success: bool,         message: str,     ) -&gt; RunResult:         if problem.best_x is None:             raise RuntimeError(                 "optimiser made no objective evaluations"             )          return RunResult(             optimiser=type(self).__name__,             problem=problem.name,             x_best=problem.best_x.copy(),             f_best=problem.best_value,             n_objective_evals=problem.n_objective_evals,             n_gradient_evals=problem.n_gradient_evals,             n_hessian_evals=problem.n_hessian_evals,             evaluations=list(problem.evaluations),             trajectory=[x.copy() for x in trajectory],             success=success,             message=message,         )   # --------------------------------------------------------------------- # Global optimisers # ---------------------------------------------------------------------   @dataclass class RandomSearch(Optimiser):     """Uniform random search within the problem bounds."""      def run(         self,         problem: Problem,         x0=None,         max_evals=500,         seed=0,     ) -&gt; RunResult:         self._start(             problem,             x0,             max_evals,         )          rng = np.random.default_rng(seed)         lower, upper = np.asarray(             problem.bounds         ).T          trajectory = []          while (             problem.n_objective_evals             &lt; max_evals         ):             x = rng.uniform(                 lower,                 upper,             )              problem(x)              # Record every evaluated location. Best-so-far             # values are stored separately in evaluations.             trajectory.append(problem.best_x.copy())          return self._result(             problem,             trajectory,             True,             "evaluation budget reached",         )   @dataclass class SimulatedAnnealing(Optimiser):     """Bounded simulated annealing with Gaussian proposals."""      initial_temperature: float = 10.0     cooling_rate: float = 0.98     step_scale: float = 0.15     minimum_temperature: float = 1e-8      def run(         self,         problem: Problem,         x0=None,         max_evals=500,         seed=0,     ) -&gt; RunResult:         x = self._start(             problem,             x0,             max_evals,         )          rng = np.random.default_rng(seed)          lower, upper = np.asarray(             problem.bounds         ).T          widths = upper - lower          value = problem(x)         trajectory = [x.copy()]          temperature = self.initial_temperature          while (             problem.n_objective_evals             &lt; max_evals         ):             proposal = (                 x                 + rng.normal(size=problem.dimension)                 * self.step_scale                 * widths             )              proposal = np.clip(                 proposal,                 lower,                 upper,             )              proposal_value = problem(proposal)             difference = proposal_value - value              accept = (                 difference &lt;= 0                 or rng.random()                 &lt; np.exp(                     -difference                     / max(temperature, 1e-300)                 )             )              if accept:                 x = proposal                 value = proposal_value                 trajectory.append(problem.best_x.copy())              temperature = max(                 self.minimum_temperature,                 temperature * self.cooling_rate,             )          return self._result(             problem,             trajectory,             True,             "evaluation budget reached",         )   @dataclass class DifferentialEvolution(Optimiser):     ""