import matplotlib.pyplot as plt
import numpy as np
from matplotlib.axes import Axes
from matplotlib.figure import Figure


Results = dict[tuple[str, str], RunResult]


def run_matrix(
    problems: Mapping[str, Problem],
    optimisers: Mapping[str, Optimiser],
    *,
    max_evals: int = 500,
    seed: int = 0,
) -&gt; Results:
    """Run every optimiser on every problem using a common budget and seed."""
    return {
        (problem_key, optimiser_key): optimiser.run(
            problem,
            max_evals=max_evals,
            seed=seed,
        )
        for problem_key, problem in problems.items()
        for optimiser_key, optimiser in optimisers.items()
    }


def _axes_grid(
    axes: object,
    nrows: int,
    ncols: int,
) -&gt; np.ndarray:
    """Always return axes as a two-dimensional array."""
    return np.asarray(
        axes,
        dtype=object,
    ).reshape(nrows, ncols)


def _objective_grid(
    problem: Problem,
    resolution: int,
) -&gt; tuple[np.ndarray, np.ndarray, np.ndarray]:
    if problem.dimension != 2:
        raise ValueError(
            f"contour plots require a 2D problem; "
            f"{problem.name!r} has dimension "
            f"{problem.dimension}"
        )

    (x_min, x_max), (y_min, y_max) = problem.bounds

    x = np.linspace(x_min, x_max, resolution)
    y = np.linspace(y_min, y_max, resolution)

    X, Y = np.meshgrid(x, y)
    Z = np.empty_like(X)

    # problem.evaluate is deliberately untracked, so plotting does not
    # alter the optimisation evaluation counts.
    for index in np.ndindex(X.shape):
        Z[index] = problem.evaluate(
            [X[index], Y[index]]
        )

    return X, Y, Z


def _transform_contours(
    Z: np.ndarray,
    scale: str,
) -&gt; np.ndarray:
    """Return a monotone display transform of an objective surface."""
    shifted = Z - np.nanmin(Z)

    if scale == "linear":
        return Z

    if scale == "log":
        # Base the scale on a small positive grid value so the transform
        # works for objectives with very different natural scales.
        positive = shifted[shifted &gt; 0]

        if positive.size:
            reference = np.nanpercentile(positive, 5)
        else:
            reference = 1.0

        reference = max(
            reference,
            np.finfo(float).eps,
        )

        return np.log1p(shifted / reference)

    if scale == "sqrt":
        return np.sqrt(shifted)

    raise ValueError(
        "contour_scale must be "
        "'linear', 'log', or 'sqrt'"
    )


def plot_trajectory_matrix(
    problems: Mapping[str, Problem],
    optimisers: Mapping[str, Optimiser],
    results: Mapping[tuple[str, str], RunResult] | None = None,
    *,
    max_evals: int = 500,
    seed: int = 0,
    resolution: int = 180,
    levels: int = 35,
    cmap: str = "magma",
    contour_scale: str = "log",
    contour_lines: bool = True,
    show_true_minima: bool = True,
    figsize_per_cell: tuple[float, float] = (3.6, 3.3),
) -&gt; tuple[Figure, np.ndarray, Results]:
    """Plot problem contours with each optimiser's trajectory overlaid.

    If ``results`` is omitted, the full experiment matrix is run first.

    Returns ``(figure, axes, results)`` so callers can further customise
    or save the figure.
    """
    if results is None:
        results = run_matrix(
            problems,
            optimisers,
            max_evals=max_evals,
            seed=seed,
        )

    results = dict(results)

    nrows = len(problems)
    ncols = len(optimisers)

    fig, axes = plt.subplots(
        nrows,
        ncols,
        figsize=(
            figsize_per_cell[0] * ncols,
            figsize_per_cell[1] * nrows,
        ),
        squeeze=False,
        constrained_layout=True,
    )

    axes = _axes_grid(
        axes,
        nrows,
        ncols,
    )

    for row, (problem_key, problem) in enumerate(
        problems.items()
    ):
        X, Y, Z = _objective_grid(
            problem,
            resolution,
        )

        display_Z = _transform_contours(
            Z,
            contour_scale,
        )

        contour_levels = np.linspace(
            np.nanmin(display_Z),
            np.nanmax(display_Z),
            levels,
        )

        for col, (optimiser_key, _) in enumerate(
            optimisers.items()
        ):
            ax: Axes = axes[row, col]

            result = results[
                (problem_key, optimiser_key)
            ]

            trajectory = np.asarray(
                result.trajectory,
                dtype=float,
            )

            ax.contourf(
                X,
                Y,
                display_Z,
                levels=contour_levels,
                cmap=cmap,
            )

            if contour_lines:
                ax.contour(
                    X,
                    Y,
                    display_Z,
                    levels=contour_levels[::3],
                    colors="black",
                    linewidths=0.35,
                    alpha=0.45,
                )

            if len(trajectory):
                ax.plot(
                    trajectory[:, 0],
                    trajectory[:, 1],
                    "-o",
                    color="white",
                    markeredgecolor="black",
                    markeredgewidth=0.25,
                    linewidth=1.2,
                    markersize=2.5,
                    alpha=0.9,
                    zorder=3,
                )

                ax.scatter(
                    *trajectory[0],
                    s=45,
                    facecolor="white",
                    edgecolor="black",
                    zorder=4,
                )

            # Best point found by the optimiser.
            ax.scatter(
                *result.x_best,
                marker="*",
                s=110,
                facecolor="red",
                edgecolor="black",
                linewidth=0.6,
                zorder=5,
            )

            # Known global minima.
            if show_true_minima and problem.true_minima:
                true_minima = np.asarray(
                    problem.true_minima
                )

                ax.scatter(
                    true_minima[:, 0],
                    true_minima[:, 1],
                    marker="X",
                    s=65,
                    facecolor="cyan",
                    edgecolor="black",
                    linewidth=0.7,
                    zorder=5,
                    label="True minimum",
                )

            if row == 0:
                ax.set_title(
                    optimiser_key
                    .replace("_", " ")
                    .title()
                )

            ax.text(
                0.02,
                0.02,
                (
                    f"best = {result.f_best:.2e}\n"
                    f"evals = "
                    f"{result.n_objective_evals}"
                ),
                transform=ax.transAxes,
                fontsize=8,
                color="white",
                va="bottom",
                bbox={
                    "facecolor": "black",
                    "alpha": 0.55,
                    "pad": 2,
                },
                zorder=6,
            )

            ax.set_xlim(problem.bounds[0])
            ax.set_ylim(problem.bounds[1])
            ax.set_aspect(
                "equal",
                adjustable="box",
            )
            ax.set_xlabel("$x_1$")

            if col == 0:
                ax.set_ylabel(
                    f"{problem.name}\n$x_2$"
                )

    return fig, axes, results


def plot_convergence_matrix(
    problems: Mapping[str, Problem],
    optimisers: Mapping[str, Optimiser],
    results: Mapping[tuple[str, str], RunResult],
    *,
    figsize_per_cell: tuple[float, float] = (3.6, 2.5),
) -&gt; tuple[Figure, np.ndarray]:
    """Plot best objective found so far against objective evaluations."""
    nrows = len(problems)
    ncols = len(optimisers)

    fig, axes = plt.subplots(
        nrows,
        ncols,
        figsize=(
            figsize_per_cell[0] * ncols,
            figsize_per_cell[1] * nrows,
        ),
        squeeze=False,
        constrained_layout=True,
    )

    axes = _axes_grid(
        axes,
        nrows,
        ncols,
    )

    for row, (problem_key, problem) in enumerate(
        problems.items()
    ):
        for col, (optimiser_key, _) in enumerate(
            optimisers.items()
        ):
            ax: Axes = axes[row, col]

            result = results[
                (problem_key, optimiser_key)
            ]

            ax.step(
                result.eval_numbers,
                result.best_values,
                where="post",
            )

            ax.set_yscale(
                "symlog",
                linthresh=1e-10,
            )

            ax.grid(alpha=0.25)

            if row == 0:
                ax.set_title(
                    optimiser_key
                    .replace("_", " ")
                    .title()
                )

            if row == nrows - 1:
                ax.set_xlabel(
                    "Objective evaluations"
                )

            if col == 0:
                ax.set_ylabel(
                    f"{problem.name}\n"
                    "Best objective"
                )

    return fig, axes

def plot_result(
    problem,
    result,
    *,
    trajectory_source="iterates",
    contour_scale="log",
    cmap="inferno",
):
    """Plot the trajectory and convergence of one optimisation result."""

    fig, (ax_trajectory, ax_convergence) = plt.subplots(
        1,
        2,
        figsize=(11, 4.5),
        constrained_layout=True,
    )

    # Plot the objective surface.
    problem.plot_contours(
        ax=ax_trajectory,
        scale=contour_scale,
        cmap=cmap,
        colorbar=False,
        show_true_minima=True,
    )

    # Select either every evaluation or accepted optimiser iterates.
    if trajectory_source == "evaluations":
        points = np.asarray([
            evaluation.x
            for evaluation in result.evaluations
        ])
    elif trajectory_source == "iterates":
        points = np.asarray(result.trajectory)
    else:
        raise ValueError(
            "trajectory_source must be "
            "'evaluations' or 'iterates'"
        )

    # Plot the search trajectory.
    if len(points):
        ax_trajectory.plot(
            points[:, 0],
            points[:, 1],
            "-o",
            color="white",
            markeredgecolor="black",
            markeredgewidth=0.4,
            linewidth=1,
            markersize=3,
            alpha=0.9,
        )

        ax_trajectory.scatter(
            *points[0],
            marker="o",
            s=70,
            facecolor="white",
            edgecolor="black",
            label="Start",
            zorder=5,
        )

    ax_trajectory.scatter(
        *result.x_best,
        marker="*",
        s=180,
        facecolor="red",
        edgecolor="black",
        label="Best found",
        zorder=6,
    )

    ax_trajectory.set_title(
        f"{result.optimiser} on {problem.name}"
    )
    ax_trajectory.legend()

    # Plot best objective so far.
    ax_convergence.step(
        result.eval_numbers,
        result.best_values,
        where="post",
    )

    ax_convergence.set(
        title="Convergence",
        xlabel="Objective evaluations",
